#!/usr/bin/env bash
# land-jobs-from-the-web.sh  ·  run from the REPO ROOT
#   bash land-jobs-from-the-web.sh && git push
#
# Owner, 17 Aug: "let users find jobs from all recruiting sites in india",
# pointing at github.com/santifer/career-ops.
#
# WHAT career-ops IS, AND WHAT WAS ACTUALLY TAKEN. It is a local-first,
# single-person job-search toolkit driven by AI-CLI prompt files — not an
# installable multi-user service. What IS reusable is its map: MIT-licensed
# connectors to the PUBLIC, unauthenticated JSON boards companies themselves
# publish on ATS vendors. This change ports three of those connectors
# (Greenhouse, Lever, Ashby) into the API as a server-side ingest, with
# credit in the file header.
#
# WHAT WAS EXPLICITLY REFUSED: scraping Naukri, LinkedIn or Indeed. Their
# terms forbid it, server IPs get banned, and a feature built on a violation
# is a feature with a countdown. "All recruiting sites in India" is not
# legitimately reachable; companies' own boards are.
#
# HOW IT WORKS:
#   · ExternalJobsService (new) sweeps the public company directories the
#     career-ops scanner uses (github.com/Feashliaa/job-board-aggregator —
#     ~16,000 boards across the three vendors), a rotating 250-board window
#     per vendor every 6 hours, concurrency 6, 12s timeouts, and a
#     consecutive-failure guard so a dead resolver aborts the run instead of
#     being fed. Slugs are validated before they touch a URL; only the three
#     vendors' own hosts are ever fetched.
#   · India postings are kept — decided from the LOCATION FIELD ONLY. A bare
#     "Remote" is a job for everywhere, and everywhere is not India: serving
#     it would be the feed inventing relevance.
#   · Reconciliation is board-scoped truth: a re-read board's rows become
#     exactly what it said, and postings it no longer lists are DELETED — the
#     city never advertises a closed role on somebody else's site. Rows not
#     re-confirmed within 30 days stop being served.
#   · Each posting is run once through the SAME skill dictionary a citizen's
#     CV parses through (jobs-engine.skillsInText, new export), so external
#     and internal roles are scored by the one matcher, in one ranked list.
#     minYears and salary are stored as 0 = "the board did not say", which
#     keeps the matcher's experience and salary terms silent rather than
#     guessing.
#   · On the card: a "via Greenhouse/Lever/Ashby" chip, no "₹0 LPA" for a
#     salary nobody stated, and ONE door — "Apply on company site ↗"
#     (target=_blank, noopener) — because Together City holds no pipeline
#     for these roles and an in-city Apply would collect a note no recruiter
#     will ever see. The apply route answers an external id with that same
#     truth instead of a bare 404.
#
# SCHEMA: two new tables (ExternalJob, ExternalScanCursor), purely additive —
# migration 20260817030000_jobs_from_the_web. Railway applies it on deploy.
# EXTERNAL_JOBS_SCAN=off (Railway env) disables all scanning if ever needed.
#
# VERIFIED IN THE SANDBOX THIS WAS WRITTEN IN: the new pure-layer spec
# (12 tests) green; web tsc clean; full web suite 889/889; all ceilings; vite
# build clean. NOT verifiable there: `prisma generate` (engine download 403s
# in the sandbox — same as the workout landing), so the API tsc and jest gates
# below are the FIRST full run those get, on this Mac. Live board fetches were
# also unreachable from the sandbox (egress allowlist): the connectors are
# ported from career-ops' own tested providers and fixture-proven here, and
# the first real sweep runs on Railway — check its logs for lines like
# "greenhouse: window 0..250 of 8333 boards — N India postings".
#
# PRECONDITION: land-the-feed-keeps-up-with-the-thumb.sh has landed.
set -uo pipefail
W=together-city-react
A=together-city-chat

say(){ printf '\n\033[1m%s\033[0m\n' "$*"; }
ok(){  printf '   \033[32m*\033[0m %s\n' "$*"; }
note(){ printf '   \033[33m~\033[0m %s\n' "$*"; }
die(){ printf '   \033[31mx\033[0m %s\n' "$*"; exit 1; }

[ -d "$W" ] && [ -d "$A" ] || die "run me from the repo root"

say "1 - preconditions"
if [ -f .git/index.lock ] && [ ! -s .git/index.lock ]; then rm -f .git/index.lock && ok "cleared an empty index.lock"; fi
git log --oneline -40 | grep 'The feed keeps up with the thumb' >/dev/null \
  || die "land-the-feed-keeps-up-with-the-thumb.sh has not landed - this script names it as its precondition"
git log --oneline -40 | grep 'Jobs from the web' >/dev/null \
  && die "already landed - re-running is a no-op by design"
# Only THIS change's paths must be clean - the tree is allowed to carry other
# work-in-progress (it does: attach panels + supplements), it just cannot sit
# on the files this patch rewrites.
git diff --quiet -- "$A/prisma/schema.prisma" "$A/src/jobs" "$W/src/features/jobs" \
  || die "uncommitted changes on this change's own files - stash them first"
ok "clean where it matters, and not landed yet"
STRAY="$(git status --porcelain -uno | grep -v '^[[:space:]]*$' || true)"
if [ -n "$STRAY" ]; then
  note "other files are dirty and are NOT part of this commit:"
  printf '%s\n' "$STRAY" | sed 's/^/       /'
  note "if a gate below fails inside one of those files, stash them and re-run:"
  note "  git stash push -u -m wip -- $W/src $A/src   ...then land, push, git stash pop"
fi

say "2 - decode the patch, prove it is the patch, prove it applies"
PATCH="$(mktemp)"
openssl base64 -d -A > "$PATCH" <<'B64EOF'

B64EOF
[ -s "$PATCH" ] || die "the decode produced an empty file"
GOT="$(shasum -a 256 "$PATCH" | awk '{print $1}')"
WANT="2d723535c999a0b5e827f30a2fafeb05435e748c13ec74024abeb44b8af8d6e9"
[ "$GOT" = "$WANT" ] || die "sha256 mismatch: got $GOT"
ok "sha256 verified"
git apply --check -C1 "$PATCH" || die "patch does not apply - the tree has moved since this was written"
git apply -C1 "$PATCH" || die "apply"
ok "applied - 11 files, 3 new under src/jobs/external, 1 migration, 1 web guard"

say "3 - the API gates"
cd "$A"
npx prisma generate || die "prisma generate - two new models need it before anything typechecks"
ok "prisma client regenerated"
npx tsc --noEmit || die "api tsc"
ok "api tsc clean"
npx jest src/jobs || die "the jobs suites - engine audit, cv entries, and the new external-ats spec"
ok "jobs suites green, the new pure layer included"
EXPECTED_RED="src/dev/dev.spec.ts src/security/query-scoping.spec.ts src/security/route-reach.spec.ts src/security/runtime-isolation.spec.ts src/shared/swallow.spec.ts src/shared/unbounded-reads.spec.ts src/shared/voice-scan.spec.ts "
OUT="$(npx jest 2>&1 || true)"
RED="$(printf '%s\n' "$OUT" | grep -E '^[[:space:]]*FAIL ' | awk '{print $2}' | sort -u | tr '\n' ' ')"
if [ "$RED" != "$EXPECTED_RED" ]; then
  printf '%s\n' "$OUT" | tail -60
  printf '\n   expected red: %s\n   actually red: %s\n' "$EXPECTED_RED" "$RED"
  die "the API suite's failing set changed - this commit is answerable for the difference"
fi
note "7 suites red on main, and still exactly those 7"
cd ..

say "4 - the web gates"
cd "$W"
npx tsc --noEmit || die "web tsc"
ok "web tsc clean"
npx vitest run src/app/jobs-from-the-web.test.ts || die "the new jobs guard"
npx vitest run || die "web suite"
ok "web suite green (889 at time of writing)"
node scripts/lint-ceiling.mjs   || die "lint ceiling"
node scripts/nav-audit.mjs      || die "nav audit"
node scripts/a11y-audit.mjs     || die "a11y ceiling"
node scripts/motion-ceiling.mjs || die "motion ceiling"
DEAD="$(node scripts/dead-export-audit.mjs --list 2>&1 | grep -E '^\s+features/' | awk '{print $2}' | sort | tr '\n' ' ')"
[ "$DEAD" = "MedicalAdvisories PlanGuidanceBanner useGemCommission " ] \
  || die "dead exports changed: $DEAD (expected the pre-existing three)"
ok "lint, nav, a11y, motion, dead-export all at ceiling"
npm run build >/dev/null 2>&1 || die "vite build"
ok "vite build clean"
cd ..

say "5 - commit"
git add "$A/prisma/schema.prisma" \
        "$A/prisma/migrations/20260817030000_jobs_from_the_web/migration.sql" \
        "$A/src/jobs/jobs-engine.ts" \
        "$A/src/jobs/jobs.service.ts" \
        "$A/src/jobs/jobs.module.ts" \
        "$A/src/jobs/external/ats.ts" \
        "$A/src/jobs/external/external-jobs.service.ts" \
        "$A/src/jobs/external/external-ats.spec.ts" \
        "$W/src/features/jobs/api.ts" \
        "$W/src/features/jobs/pages/Matches.tsx" \
        "$W/src/app/jobs-from-the-web.test.ts" \
        land-jobs-from-the-web.sh
git commit -m "Jobs from the web" -m \
"Owner: let users find jobs from all recruiting sites in India, pointing at
career-ops. What career-ops actually is: a local-first, single-person toolkit
driven by AI-CLI prompts - not an installable service. What was taken is its
map: MIT-licensed connectors to the public, unauthenticated JSON boards
companies themselves publish on Greenhouse, Lever and Ashby, ported into the
API as a server-side ingest with credit in the file header. Scraping Naukri,
LinkedIn or Indeed was refused: their terms forbid it, and a feature built on
a violation is a feature with a countdown.

ExternalJobsService sweeps the public company directories career-ops scans
(~16,000 boards across the three vendors) in a rotating 250-board window per
vendor every six hours, keeps postings whose LOCATION names India or an
Indian city - a bare Remote is a job for everywhere, and everywhere is not
India - and reconciles board-scoped truth: a re-read board's rows become
exactly what it said, vanished postings are deleted, and rows not
re-confirmed in 30 days stop being served. The city never advertises a
closed role on somebody else's site.

Each posting parses once through the same skill dictionary a citizen's CV
does (skillsInText, new engine export), so one matcher ranks internal and
external roles in one list. minYears and salary store 0 = the board did not
say, keeping the matcher's experience and salary terms silent rather than
guessing. On the card: a via-Greenhouse/Lever/Ashby chip, no invented salary
line, and one honest door - Apply on company site - because Together City
holds no pipeline for these roles and an in-city Apply would collect a note
no recruiter will ever see. The apply route answers an external id with that
same sentence instead of a bare 404.

Two additive tables (ExternalJob, ExternalScanCursor). EXTERNAL_JOBS_SCAN=off
disables scanning. Slugs validate before touching a URL; only the vendors'
own hosts are fetched; a run aborts after 40 consecutive network failures
rather than feeding a dead resolver." \
  || die "commit"
ok "committed"
git log --oneline -1

say "done - now: git push"
say "NOTE: a migration. Railway must run 20260817030000_jobs_from_the_web on deploy,"
say "then the first sweep starts on boot (empty table) - watch for"
say "  ExternalJobs: greenhouse: window 0..250 of ~8333 boards - N India postings"
